// Rename the form's column headers and keep only last month's responses.
const month = $now.minus({ months: 1 }).toFormat('yyyy-MM');
return $input.all().map(i => i.json).map(r => ({
  timestamp: String(r['Timestamp'] ?? ''), id: String(r['Response ID'] ?? ''), workshop: r['Workshop'] ?? '',
  rating: Number(r['Overall rating (1-5)']), useful: r['What was most useful?'] ?? '',
  improve: r['What should we improve?'] ?? '', other: r['Any other comments?'] ?? '',
  month: String(r['Month'] || String(r['Timestamp'] ?? '').slice(0, 7)),
})).filter(r => r.id && r.month === month).map(json => ({ json }));

// Ratings are worked out here by code, never by the AI. The keyword check is a backup to the AI flags.
const KEYWORDS = /safeguard|harass|complain|bully|unsafe|uncomfortable|abuse|discriminat/;
const rows = $input.all().map(i => i.json);
if (!rows.length) return [];  // empty month: stop before the AI step
const spread = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
let total = 0, rated = 0;
for (const r of rows) {
  const n = Number(r.rating);
  if (n >= 1 && n <= 5) { spread[n]++; total += n; rated++; }
}
const responses = rows.map(r => ({ id: r.id, useful: r.useful || '', improve: r.improve || '', other: r.other || '' }));
const keywordFlagged = responses
  .filter(r => KEYWORDS.test((r.useful + ' ' + r.improve + ' ' + r.other).toLowerCase()))
  .map(r => r.id);
// One line per response, with its ID. Ratings are left out of the AI input on purpose.
const responsesText = rows.map(r => '[' + r.id + '] Workshop: ' + r.workshop + ' | Most useful: ' + (r.useful || '') +
  ' | Improve: ' + (r.improve || '') + ' | Other comments: ' + (r.other || '')).join('\n');
return [{ json: {
  month: rows[0].month,
  count: rows.length,
  average: rated ? (Math.round(total / rated * 100) / 100).toFixed(2) : 'n/a',
  spread, keywordFlagged, responses, responsesText,
} }];

// Take the text block from Claude's reply and parse it. Anything unusable means a person reads the raw responses.
const stats = $('Ratings and keyword check').first().json;
const res = $input.first().json || {};
const block = (Array.isArray(res.content) ? res.content : []).find(b => b && b.type === 'text');
let ai = null, problem = '';
if (res.stop_reason !== 'end_turn') {
  problem = 'stop reason: ' + (res.stop_reason || (res.error ? 'the API call failed' : 'none'));
} else if (!block) {
  problem = 'the reply had no text block';
} else {
  try { ai = JSON.parse(block.text); } catch (e) { problem = 'the reply was not valid JSON'; }
  if (ai && !Array.isArray(ai.themes)) { ai = null; problem = 'the reply did not match the schema'; }
}
return [{ json: { ...stats, ok: !problem, problem, ai } }];

// Checks the AI's work against the data. Nothing here trusts the AI's own numbers.
const d = $input.first().json;
const norm = s => String(s || '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/\s+/g, ' ').trim();
const byId = {};
for (const r of d.responses) byId[r.id] = [r.useful, r.improve, r.other].map(norm);
const warnings = [], quoteChecks = [];
const flags = {};
for (const id of d.keywordFlagged) flags[id] = { id, byAI: false, byKeyword: true, category: '' };
if (d.ok) {
  const ai = d.ai;
  if (ai.total_responses_analysed !== d.count)
    warnings.push('The sheet has ' + d.count + ' responses but the AI reports reading ' + ai.total_responses_analysed + '. Theme counts may be off.');
  for (const t of ai.themes) {
    const ids = [...new Set(t.response_ids || [])];
    if (t.response_count < 2 || ids.length < 2)
      warnings.push('Theme "' + t.name + '" has fewer than 2 responses. It belongs in other comments.');
    if ((t.response_ids || []).length !== t.response_count)
      warnings.push('Theme "' + t.name + '" says ' + t.response_count + ' responses but lists ' + (t.response_ids || []).length + ' IDs.');
    for (const q of t.quotes || []) {
      const fields = byId[q.response_id];
      const found = !!fields && fields.some(f => f.includes(norm(q.text)));
      quoteChecks.push({ theme: t.name, response_id: q.response_id, text: q.text, found });
      if (!found) warnings.push('Quote "' + q.text + '" (' + q.response_id + ') was not found word for word in that response. Check the sheet.');
    }
  }
  for (const f of ai.flagged_for_follow_up || []) {
    flags[f.response_id] = { id: f.response_id, byAI: true, byKeyword: !!(flags[f.response_id] && flags[f.response_id].byKeyword), category: f.category };
  }
}
const needsPerson = Object.values(flags).sort((a, b) => a.id.localeCompare(b.id, 'en', { numeric: true }));
return [{ json: { ...d, warnings, quoteChecks, needsPerson } }];

// Builds the one-page report email for the programme lead, or the raw responses if the AI step failed.
const WINE = '#4a1424', RED = '#b3202a', INK = '#1d1416', MUTED = '#5f5456', LINE = '#d9d4d5';
const TO = 'lead@example.org';
const d = $input.first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const [y, m] = String(d.month).split('-');
const monthName = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'][Number(m) - 1] + ' ' + y;
const label = t => '<div style="margin:22px 0 8px;font:700 12px Arial,sans-serif;letter-spacing:1.5px;text-transform:uppercase;color:' + (t[1] || WINE) + '">' + t[0] + '</div>';
const box = inner => '<div style="padding:12px 14px;border:1px solid ' + RED + ';border-radius:6px">' + inner + '</div>';
const list = items => items.length ? '<ul style="margin:0;padding-left:20px">' + items.map(x => '<li style="margin:3px 0">' + x + '</li>').join('') + '</ul>' : '<p style="margin:0;color:' + MUTED + '">None.</p>';
const head =
  '<div style="font-family:Helvetica,Arial,sans-serif;color:' + INK + ';max-width:640px;margin:0 auto;border:1px solid ' + LINE + ';background:#fff">' +
  '<div style="background:' + WINE + ';color:#fff;padding:20px 28px"><div style="font-family:Georgia,serif;font-size:19px;font-weight:700;letter-spacing:1.5px">LUMEN TEACHER TRAINING ACADEMY</div>' +
  '<div style="width:44px;height:2px;background:' + RED + ';margin:8px 0"></div><div style="font-size:12px;letter-spacing:1px">Monthly workshop feedback</div></div>' +
  '<div style="padding:26px 28px;font-size:14px;line-height:1.6">';
const foot = '</div><div style="border-top:1px solid ' + LINE + ';padding:14px 28px;font-size:12px;color:' + MUTED + '">' +
  'Themes, quotes and flags are drafted by AI and checked by the flow. Ratings are worked out by code. Lumen Teacher Training Academy (a fictional organisation).</div></div>';
const flagLine = d.needsPerson.length ? d.needsPerson.map(f => '<b>' + esc(f.id) + '</b> (' +
  [f.byAI ? 'AI: ' + esc(f.category) : '', f.byKeyword ? 'keyword check' : ''].filter(Boolean).join(', ') + ')').join('<br>') : 'None this month.';

if (!d.ok) {
  const html = head + '<h1 style="margin:0 0 12px;font-family:Georgia,serif;font-size:22px;color:' + WINE + '">Please read these responses yourself</h1>' +
    '<p>The AI step did not return a usable report this month (' + esc(d.problem) + '). Nothing has been summarised.</p>' +
    '<p><b>Responses:</b> ' + d.count + ' &middot; <b>Average rating:</b> ' + d.average + ' &middot; <b>Keyword-flagged:</b> ' + (esc(d.keywordFlagged.join(', ')) || 'none') + '</p>' +
    '<pre style="white-space:pre-wrap;font-family:Consolas,monospace;font-size:12px;padding:12px;border:1px solid ' + LINE + '">' + esc(d.responsesText) + '</pre>' + foot;
  return [{ json: { to: TO, subject: 'Feedback for ' + monthName + ' needs a manual read', html } }];
}

const ai = d.ai;
const cell = 'padding:9px 10px;border-top:1px solid ' + LINE + ';vertical-align:top';
const tile = (big, small) => '<td style="width:33%;padding:12px;border:1px solid ' + LINE + ';text-align:center">' + big + '<div style="font-size:12px;color:' + MUTED + '">' + small + '</div></td>';
const s = d.spread;
const rowsHtml = ai.themes.map(t => {
  const qs = (t.quotes || []).map(q => {
    const ok = d.quoteChecks.find(c => c.theme === t.name && c.response_id === q.response_id && c.text === q.text);
    return '<div style="font-style:italic">&ldquo;' + esc(q.text) + '&rdquo; <span style="font-style:normal;font-size:11px;color:' + MUTED + '">' + esc(q.response_id) + '</span>' +
      (ok && ok.found ? '' : '<br><span style="font-style:normal;font-size:11px;color:' + RED + ';font-weight:700">not found word for word, check the sheet</span>') + '</div>';
  }).join('');
  return '<tr><td style="' + cell + '"><b>' + esc(t.name) + '</b><br><span style="font-size:12px;color:' + MUTED + '">' + esc(t.sentiment) + '</span></td>' +
    '<td style="' + cell + ';text-align:center">' + t.response_count + (t.response_count < 2 ? '<br><span style="font-size:11px;color:' + RED + ';font-weight:700">under 2</span>' : '') + '</td>' +
    '<td style="' + cell + '">' + (qs || '<span style="color:' + MUTED + '">No exact quote</span>') + '</td></tr>';
}).join('');
const found = d.quoteChecks.filter(c => c.found).length;
const html = head +
  '<h1 style="margin:0 0 14px;font-family:Georgia,serif;font-size:22px;color:' + WINE + '">Workshop feedback, ' + monthName + '</h1>' +
  (d.warnings.length ? box('<div style="font-weight:700;color:' + RED + ';margin-bottom:4px">Check before you rely on this</div>' + list(d.warnings.map(esc))) + '<div style="height:14px"></div>' : '') +
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr>' +
  tile('<div style="font-size:26px;font-weight:700;color:' + WINE + '">' + d.count + '</div>', 'responses') +
  tile('<div style="font-size:26px;font-weight:700;color:' + WINE + '">' + d.average + '</div>', 'average rating out of 5') +
  tile('<div style="font-size:13px">5: ' + s[5] + ' &middot; 4: ' + s[4] + ' &middot; 3: ' + s[3] + '<br>2: ' + s[2] + ' &middot; 1: ' + s[1] + '</div>', 'ratings spread') +
  '</tr></table>' +
  '<div style="font-size:12px;color:' + MUTED + ';margin-top:6px">AI analysed ' + ai.total_responses_analysed + ' responses. ' + found + ' of ' + d.quoteChecks.length + ' quotes found word for word.</div>' +
  label(['Themes']) +
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid ' + LINE + ';font-size:13.5px"><tr>' +
  '<th style="text-align:left;padding:8px 10px;background:' + WINE + ';color:#fff">Theme</th><th style="padding:8px 10px;background:' + WINE + ';color:#fff">Responses</th>' +
  '<th style="text-align:left;padding:8px 10px;background:' + WINE + ';color:#fff">In their words</th></tr>' + rowsHtml + '</table>' +
  label(['Suggestions from respondents']) + list(ai.suggestions.map(x => esc(x.suggestion) + ' <span style="font-size:11px;color:' + MUTED + '">' + esc(x.response_ids.join(', ')) + '</span>')) +
  label(['Other comments (raised once)']) + list(ai.other_comments.map(x => esc(x.comment) + ' <span style="font-size:11px;color:' + MUTED + '">' + esc(x.response_id) + '</span>')) +
  label(['Needs a person', RED]) +
  box(flagLine + '<div style="margin-top:6px;font-size:13px;color:' + MUTED + '">Please read these responses in full in the sheet. A flag is a prompt to look, not a judgement.</div>') +
  foot;
return [{ json: { to: TO, subject: 'Workshop feedback report: ' + monthName + (d.warnings.length ? ' (check warnings)' : ''), warnings: d.warnings, html } }];

// A separate email to the safeguarding lead and the programme lead when anything is flagged, by the AI or by keyword.
const d = $input.first().json;
if (!d.needsPerson.length) return [];
const lines = d.needsPerson.map(f => f.id + ': ' + [f.byAI ? 'AI flag (' + f.category + ')' : '', f.byKeyword ? 'keyword check' : ''].filter(Boolean).join(' and '));
return [{ json: { to: 'safeguarding.lead@example.org, lead@example.org', subject: 'Feedback to follow up today: ' + d.month,
  count: d.needsPerson.length,
  text: 'Last month\'s feedback has responses that may need follow-up. Please read them in full in the sheet today.\n\n' +
    lines.join('\n') + '\n\nA flag is a prompt to look, not a judgement. Follow the academy\'s safeguarding and complaints procedures.' } }];
